import * as React from "react";

import { useListFiltered } from "../lib/list-query";
import { cn } from "../lib/utils";
import { Button } from "../ui/button";
import { type EmptyGhost, EmptyGhostScope, EmptyState } from "../ui/empty";
import type { IconSource } from "../ui/icon";
import { Input } from "../ui/input";
import { Media, Tile } from "../ui/item";
import { List, ListRow, ListSection } from "../ui/list";

import listStyles from "../ui/data.module.css";
import styles from "./tile-picker.module.css";

export type TilePickerItem = {
  value: string;
  title: string;
  /** The line under the title. Wins over category there. */
  description?: React.ReactNode;
  /** A short group name, such as AWS or CI/CD. Shown under the title when there is no description, and what groupBy groups by. */
  category?: string;
  /** @deprecated Use category. */
  eyebrow?: string;
  /** Sits right after the title, such as a plan Badge. */
  badge?: React.ReactNode;
  icon?: IconSource;
  /** A logo or image, framed like an icon. Ignored when icon is set. */
  media?: React.ReactNode;
  /** Listed under the popular section, or in the featured strip, while the search is empty. */
  popular?: boolean;
  disabledReason?: string;
  /** Extra words the search matches, such as a vendor's other product names. */
  keywords?: readonly string[];
  /** Always listed, after any matches, even when a search doesn't match it. For catch-alls such as a custom integration. With pinnedLabel, pinned items get a section of their own. */
  pinned?: boolean;
  /** Makes the tile a link that navigates instead of calling onSelect. */
  href?: string;
  /** Opens href in a new tab and marks the tile as external. */
  external?: boolean;
};

export type TilePickerProps = Omit<React.ComponentPropsWithoutRef<"div">, "onSelect"> & {
  items: readonly TilePickerItem[];
  /** Called with a picked item's value. Items with an href navigate instead. */
  onSelect?: (value: string) => void;
  /** grid shows tiles; list shows a List of rows, each with the description or category under its name. */
  layout?: "grid" | "list";
  /** compact shows the title only, so about twice as many tiles fit. Grid only. */
  density?: "comfortable" | "compact";
  /** Heads each category with its count. A search flattens the groups and shows the category under each title. */
  groupBy?: "category";
  /** section lists popular items under their own label and again below. featured shows them as a strip of larger tiles, with the description in mono, that are not repeated below. Grid only. */
  popular?: "section" | "featured";
  /** Heads the pinned items, which then leave the catalog and sit under this label, below any search results. */
  pinnedLabel?: string;
  /** Off for a short choice, such as three sources. */
  searchable?: boolean;
  /** The selected item's value. */
  value?: string;
  searchLabel?: string;
  searchPlaceholder?: string;
  popularLabel?: string;
  /** Heads the full list when popular or pinned items are shown above it. Ignored with groupBy. */
  allLabel?: string;
  /** Names what the search found nothing of, as in No items match. */
  noun?: string;
  /** Shown in place of the grid when there are no items at all, such as an EmptyState. */
  empty?: React.ReactNode;
  /** The ghost behind an Empty in the empty slot. Defaults to cards; a search that finds nothing never draws one. */
  ghost?: EmptyGhost;
  /** The items are narrowed outside the picker, so an empty picker means no matches and draws no ghost. Inside a ListQueryScope it follows the FilterBar unless passed. */
  filtered?: boolean;
};

const categoryOf = (item: TilePickerItem) => item.category ?? item.eyebrow;

const matches = (item: TilePickerItem, query: string) =>
  [
    item.title,
    categoryOf(item),
    typeof item.description === "string" ? item.description : undefined,
    ...(item.keywords ?? [])
  ].some((text) => text?.toLowerCase().includes(query));

type Group = {
  id: string;
  label?: string;
  items: readonly TilePickerItem[];
  counted?: boolean;
  pinned?: boolean;
};

/**
 * Search plus a responsive grid of Tiles, or a List of rows. With an empty search, popular items
 * come first (as a section or a featured strip), then pinned items under pinnedLabel, then every
 * item, grouped by category with groupBy. A search lists its matches flat, then the pinned items,
 * and finding nothing offers to clear it above them. The grid adds columns as the container
 * widens, so it fits a sheet or a page without a frame of its own.
 */
export function TilePicker({
  items,
  onSelect,
  layout = "grid",
  density = "comfortable",
  groupBy,
  popular: popularStyle = "section",
  pinnedLabel,
  searchable = true,
  value,
  searchLabel = "Search",
  searchPlaceholder,
  popularLabel = "Popular",
  allLabel = "All",
  noun = "items",
  empty,
  ghost,
  filtered: filteredProp,
  className,
  ref,
  ...props
}: TilePickerProps & { ref?: React.Ref<HTMLDivElement> }) {
  const [search, setSearch] = React.useState("");
  const listFiltered = useListFiltered();
  const filtered = filteredProp ?? listFiltered;
  const inputRef = React.useRef<HTMLInputElement>(null);
  const query = searchable ? search.trim().toLowerCase() : "";
  const compact = layout === "grid" && density === "compact";
  const media = (item: TilePickerItem) =>
    (item.icon || item.media) && (
      <Media icon={item.icon} size={compact ? "sm" : "md"}>
        {item.media}
      </Media>
    );
  const tile = (item: TilePickerItem, featured: boolean, pinned: boolean) => {
    let detail: React.ReactNode = item.description ?? categoryOf(item);
    if (featured)
      detail = item.description && <span className={styles.host}>{item.description}</span>;
    else if (compact && !pinned && !(query && groupBy)) detail = undefined;
    const shared = {
      layout: featured ? ("stacked" as const) : ("inline" as const),
      title: item.title,
      description: detail,
      badge: item.badge,
      disabledReason: item.disabledReason,
      selected: value === undefined ? undefined : value === item.value,
      media: media(item),
      className: cn(featured && styles.featured, pinned && styles.pinned)
    };
    return item.href ? (
      <Tile key={item.value} {...shared} href={item.href} external={item.external} />
    ) : (
      <Tile key={item.value} {...shared} onClick={() => onSelect?.(item.value)} />
    );
  };
  const row = (item: TilePickerItem) => {
    const shared = {
      value: item.value,
      label: item.title,
      title: item.title,
      description: item.disabledReason ?? item.description ?? categoryOf(item),
      media: media(item),
      badge: item.badge,
      disabled: Boolean(item.disabledReason),
      current: value === item.value
    };
    return item.href ? (
      <ListRow key={item.value} {...shared} href={item.href} external={item.external} />
    ) : (
      <ListRow key={item.value} {...shared} onClick={() => onSelect?.(item.value)} />
    );
  };
  const grid = (group: Group) => (
    <div className={styles.grid} data-density={compact ? "compact" : undefined}>
      {group.items.map((item) => tile(item, false, Boolean(group.pinned)))}
    </div>
  );
  const head = (label: string, count?: number) => (
    <div className={styles.head}>
      <h3 className={listStyles.sectionLabel}>{label}</h3>
      {count !== undefined && <span className={listStyles.sectionMeta}>{count}</span>}
    </div>
  );
  const render = (groups: readonly Group[]) => {
    const visible = groups.filter((group) => group.items.length > 0);
    if (layout === "list")
      return (
        <List label={searchLabel}>
          {visible.map((group) =>
            group.label ? (
              <ListSection
                key={group.id}
                label={group.label}
                meta={group.counted ? String(group.items.length) : undefined}
              >
                {group.items.map(row)}
              </ListSection>
            ) : (
              <React.Fragment key={group.id}>{group.items.map(row)}</React.Fragment>
            )
          )}
        </List>
      );
    return visible.map((group) =>
      group.label ? (
        <section key={group.id} className={styles.section} aria-label={group.label}>
          {head(group.label, group.counted ? group.items.length : undefined)}
          {grid(group)}
        </section>
      ) : (
        <React.Fragment key={group.id}>{grid(group)}</React.Fragment>
      )
    );
  };
  const ownPinned = pinnedLabel ? items.filter((item) => item.pinned) : [];
  const pinnedGroup: Group = { id: "pinned", label: pinnedLabel, items: ownPinned, pinned: true };
  let body: React.ReactNode;
  if (!query && items.length === 0 && empty !== undefined)
    body = <EmptyGhostScope ghost={ghost ?? (filtered ? false : "cards")}>{empty}</EmptyGhostScope>;
  else if (query) {
    const found = items.filter((item) => matches(item, query) && !ownPinned.includes(item));
    const trailing = pinnedLabel
      ? []
      : items.filter((item) => item.pinned && !matches(item, query));
    body = (
      <>
        {found.length === 0 && (
          <EmptyState
            ghost={false}
            size="sm"
            media="bare"
            icon="search"
            title={`No ${noun} match "${search.trim()}"`}
            actions={
              <Button
                variant="outline"
                onClick={() => {
                  setSearch("");
                  inputRef.current?.focus();
                }}
              >
                Clear search
              </Button>
            }
          />
        )}
        {render([{ id: "results", items: [...found, ...trailing] }, pinnedGroup])}
      </>
    );
  } else {
    const popular = items.filter((item) => item.popular && !ownPinned.includes(item));
    const featured = popularStyle === "featured" && layout === "grid" ? popular : [];
    const rest = items.filter((item) => !ownPinned.includes(item) && !featured.includes(item));
    const lead: Group[] = [
      { id: "popular", label: popularLabel, items: featured.length > 0 ? [] : popular },
      pinnedGroup
    ];
    const above = featured.length > 0 || lead.some((group) => group.items.length > 0);
    let catalog: Group[] = [{ id: "all", label: above ? allLabel : undefined, items: rest }];
    if (groupBy) {
      const groups = new Map<string, TilePickerItem[]>();
      for (const item of rest) {
        const label = categoryOf(item) ?? allLabel;
        groups.set(label, [...(groups.get(label) ?? []), item]);
      }
      catalog = [...groups]
        .sort(([a], [b]) => a.localeCompare(b))
        .map(([label, members]) => ({
          id: `category:${label}`,
          label,
          items: members,
          counted: true
        }));
    }
    body = (
      <>
        {featured.length > 0 && (
          <section className={styles.section} aria-label={popularLabel}>
            {head(popularLabel)}
            <div className={styles.strip}>{featured.map((item) => tile(item, true, false))}</div>
          </section>
        )}
        {render([...lead, ...catalog])}
      </>
    );
  }
  return (
    <div ref={ref} data-slot="tile-picker" className={cn(styles.picker, className)} {...props}>
      {searchable && (
        <Input
          ref={inputRef}
          icon="search"
          aria-label={searchLabel}
          placeholder={searchPlaceholder ?? searchLabel}
          value={search}
          data-cipher-escape-owner={search ? "" : undefined}
          onChange={(event) => setSearch(event.target.value)}
          onKeyDown={(event) => {
            if (event.key === "Escape" && search) {
              event.preventDefault();
              event.stopPropagation();
              setSearch("");
            }
          }}
        />
      )}
      {body}
    </div>
  );
}
TilePicker.displayName = "TilePicker";

.picker {
  display: flex;
  flex-direction: column;
  gap: var(--cipher-space-content-group);
  width: 100%;
  min-width: 0;
}
.section {
  display: flex;
  flex-direction: column;
  gap: var(--cipher-space-8);
  min-width: 0;
}
.head {
  display: flex;
  align-items: baseline;
  gap: var(--cipher-space-8);
  min-width: 0;
}
.head > * {
  margin: 0;
}
.grid {
  display: grid;
  grid-template-columns: repeat(
    auto-fill,
    minmax(min(100%, var(--cipher-size-tile-inline-min)), 1fr)
  );
  gap: var(--cipher-space-12);
}
.grid[data-density="compact"] {
  grid-template-columns: repeat(auto-fill, minmax(min(100%, var(--cipher-size-tile-min)), 1fr));
}
.grid > .pinned {
  border-style: dashed;
}
.strip {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: minmax(var(--cipher-size-tile-min), 1fr);
  gap: var(--cipher-space-12);
  overflow-x: auto;
  overscroll-behavior-x: contain;
}
.strip > .featured {
  background: var(--cipher-tint);
}
.host {
  font-family: var(--cipher-type-mono-sm-font-family);
  font-size: var(--cipher-type-mono-sm-font-size);
  line-height: var(--cipher-type-mono-sm-line-height);
  font-weight: var(--cipher-type-mono-sm-font-weight);
  letter-spacing: var(--cipher-type-mono-sm-letter-spacing);
}

.gridShell,
.tableShell,
.listShell {
  color: var(--cipher-ink);
}
.tableShell,
.listShell {
  position: relative;
}
/* A background refetch keeps the rows and draws one thin sweep on the top edge, after a delay so a quick refetch never flashes it. */
.refreshing {
  position: absolute;
  inset: 0 0 auto;
  z-index: 1;
  height: var(--cipher-space-2);
  overflow: hidden;
  pointer-events: none;
  opacity: 0;
  animation: refreshShow var(--cipher-duration-moderate) var(--cipher-ease-fade)
    var(--cipher-duration-slow) forwards;
}
.refreshing::before {
  content: "";
  position: absolute;
  inset-block: 0;
  inset-inline-start: 0;
  width: 30%;
  background: var(--cipher-ink);
  animation: refreshTravel calc(var(--cipher-duration-slow) * 5) var(--cipher-ease-standard)
    infinite;
}
@keyframes refreshShow {
  to {
    opacity: 1;
  }
}
@keyframes refreshTravel {
  from {
    transform: translateX(-100%);
  }
  to {
    transform: translateX(340%);
  }
}
@media (prefers-reduced-motion: reduce) {
  .refreshing::before {
    width: 100%;
    background: var(--cipher-line);
    animation: none;
  }
}
.gridScroll,
.tableScroll {
  border-radius: 0;
  overflow: auto;
  position: relative;
}
.tableScroll {
  scroll-padding-block: var(--cipher-focus-clearance);
}
.tableScroll:has(> :is([data-slot="data-table-more"], [data-slot="data-table-pagination"])) {
  scroll-padding-block-end: calc(var(--cipher-space-40) + var(--cipher-focus-clearance));
}
.tableScroll[data-flow]:has(
    > :is([data-slot="data-table-more"], [data-slot="data-table-pagination"])
  )
  tbody
  :where(tr, tr *) {
  scroll-margin-block-end: calc(var(--cipher-space-40) + var(--cipher-focus-clearance));
}
.tableScroll[data-flow] {
  overflow-x: clip;
  overflow-y: visible;
}
.tableScroll tbody > tr {
  scroll-margin-top: var(--cipher-space-40);
}
.gridScroll {
  background: var(--cipher-surface);
  border: var(--cipher-size-control-border) solid var(--cipher-line-soft);
}
.gridScroll {
  font-family: var(--cipher-type-mono-font-family);
  font-size: var(--cipher-type-mono-font-size);
  line-height: var(--cipher-type-mono-line-height);
  font-weight: var(--cipher-type-mono-font-weight);
  letter-spacing: var(--cipher-type-mono-letter-spacing);
}
.tree:focus-visible {
  outline: 2px solid var(--cipher-ink);
  outline-offset: -2px;
}
.gridScroll[aria-activedescendant]:focus-visible {
  outline: none;
}
.gridRow,
.gridHead {
  display: grid;
  width: max-content;
  min-width: 100%;
}
.gridRow {
  border-bottom: var(--cipher-size-control-border) solid var(--cipher-line-soft);
}
.gridRow[data-last] {
  border-bottom-color: transparent;
}
/* With a footer the grid is a framed shell: the borderless tint frame holds the inset
   grid on top and the footer below, so there is exactly one edge at the bottom. */
.gridShell[data-footer] {
  --cipher-frame-pad: var(--cipher-space-3);
  padding: var(--cipher-frame-pad) var(--cipher-frame-pad) 0;
  background: var(--cipher-tint);
  border-radius: 0;
}
.gridShell[data-footer] > .gridScroll {
  border-radius: 0;
  box-shadow: var(--cipher-shadow-raised);
}
.gridShell[data-footer] > .status,
.gridShell[data-footer] > .actions {
  padding-inline: var(--cipher-space-8);
}
.gridFooter {
  display: flex;
  align-items: center;
  gap: var(--cipher-space-12);
  min-height: var(--cipher-space-40);
  padding: var(--cipher-space-4) var(--cipher-space-8);
  color: var(--cipher-muted);
  font-family: var(--cipher-type-caption-font-family);
  font-size: var(--cipher-type-caption-font-size);
  line-height: var(--cipher-type-caption-line-height);
  font-variant-numeric: tabular-nums;
}
.gridAddHeader {
  display: flex;
  align-items: center;
  padding-inline: var(--cipher-space-4);
}
.gridAddForm {
  display: grid;
  gap: var(--cipher-space-6);
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
}
.gridAddCheck {
  display: flex;
  align-items: center;
  gap: var(--cipher-space-8);
  margin-top: var(--cipher-space-4);
}
.gridAddActions {
  display: flex;
  justify-content: flex-end;
  gap: var(--cipher-space-8);
  margin-top: var(--cipher-space-8);
}
.gridKey {
  flex: none;
  color: var(--cipher-muted);
}
.gridHead {
  position: sticky;
  top: 0;
  z-index: 2;
  background: var(--cipher-paper);
  min-height: var(--cipher-size-control-sm);
  border-bottom: var(--cipher-size-control-border) solid var(--cipher-line-soft);
  color: var(--cipher-muted);
}
.gridHeader {
  position: relative;
  display: flex;
  align-items: center;
  gap: 0;
  border-right: var(--cipher-size-control-border) solid var(--cipher-line-soft);
  padding: 0 var(--cipher-space-12) 0 0;
  overflow: visible;
}
.gridHeader[data-selected] {
  background: var(--cipher-select);
  color: var(--cipher-ink);
}
.gridHeaderLabel {
  display: flex;
  flex: 1;
  min-width: 0;
  align-items: center;
  gap: var(--cipher-space-6);
  padding-inline: var(--cipher-space-8);
  overflow: hidden;
}
.gridHeaderLabel > span {
  display: inline-flex;
  align-items: center;
  gap: var(--cipher-space-4);
  color: var(--cipher-ink);
  font-family: var(--cipher-type-label-font-family);
  font-size: var(--cipher-type-label-font-size);
  line-height: var(--cipher-type-label-line-height);
  font-weight: var(--cipher-type-label-font-weight);
  letter-spacing: var(--cipher-type-label-letter-spacing);
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.gridHeader small {
  min-width: 0;
  overflow: hidden;
  color: var(--cipher-muted);
  font-family: var(--cipher-type-mono-sm-font-family);
  font-size: var(--cipher-type-mono-sm-font-size);
  line-height: var(--cipher-type-mono-sm-line-height);
  font-weight: var(--cipher-type-mono-sm-font-weight);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.gridSort[data-active] {
  color: var(--cipher-ink);
}
.gridSort:not([data-active]) {
  opacity: 0;
}
.gridHeader:is(:hover, :focus-within) > .gridSort {
  opacity: 1;
}
.gutter {
  position: sticky;
  left: 0;
  z-index: 1;
  background: var(--cipher-surface);
  padding: var(--cipher-space-6) var(--cipher-space-8);
  min-width: var(--cipher-space-40);
  text-align: right;
  color: var(--cipher-faint);
  border-right: var(--cipher-size-control-border) solid var(--cipher-line-soft);
}
.gridHead > .gutter {
  background: inherit;
}
.gutter[data-selected] {
  background: var(--cipher-select);
  color: var(--cipher-ink);
}
.gutter button {
  font: inherit;
  color: inherit;
  background: none;
  border: 0;
}
.gridCell {
  padding: var(--cipher-space-6) var(--cipher-space-8);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  border-right: var(--cipher-size-control-border) solid var(--cipher-line-soft);
  position: relative;
}
:global(.cipher) {
  --overlay-hover: var(--cipher-hover-mix);
  --overlay-press: var(--cipher-press-mix);
}
.gridRow:hover > .gridCell:not([data-selected], [data-dirty]) {
  background: color-mix(in oklab, var(--cipher-mix-ink) var(--overlay-hover), transparent);
}
.gridCell[data-selected] {
  background: var(--cipher-accent-wash);
}
.gridNull {
  color: var(--cipher-faint);
  font-style: italic;
}
.gridCell[data-dirty] {
  background: var(--cipher-warn-wash);
}
.gridCell[data-active] {
  outline: 2px solid var(--cipher-ink);
  outline-offset: -2px;
}
.gridCell textarea {
  font: inherit;
  color: inherit;
  background: var(--cipher-surface);
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  resize: none;
  border: 0;
  box-sizing: border-box;
  outline: 2px solid var(--cipher-ink);
  outline-offset: -2px;
  padding: var(--cipher-space-6) var(--cipher-space-8);
  line-height: inherit;
  white-space: pre;
  overflow: hidden;
}
.gridCell textarea[aria-invalid="true"] {
  outline-color: var(--cipher-bad);
}
.resize {
  position: absolute;
  top: 0;
  bottom: 0;
  right: calc(-1 * (var(--cipher-space-12) + var(--cipher-size-control-border)));
  z-index: 1;
  width: var(--cipher-space-24);
  cursor: col-resize;
  touch-action: none;
}
.resize::after {
  content: "";
  position: absolute;
  inset-block: 0;
  left: calc(50% - var(--cipher-size-control-border));
  width: var(--cipher-size-control-border);
  background: transparent;
  pointer-events: none;
  transition: background-color var(--cipher-duration-fast) var(--cipher-ease-fade);
}
.resize:hover::after {
  background: var(--cipher-control);
}
.resize:focus-visible {
  outline: 2px solid var(--cipher-ink);
  outline-offset: -2px;
}
.status {
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
  font-weight: var(--cipher-type-small-font-weight);
  letter-spacing: var(--cipher-type-small-letter-spacing);
  color: var(--cipher-muted);
  padding: var(--cipher-space-8) 0 0;
  overflow-wrap: anywhere;
}
.actions {
  display: flex;
  align-items: center;
  gap: var(--cipher-space-12);
  flex-wrap: wrap;
  padding: var(--cipher-space-12) 0 0;
}
.actions [role="alert"] {
  color: var(--cipher-bad);
}
.empty {
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
  font-weight: var(--cipher-type-small-font-weight);
  letter-spacing: var(--cipher-type-small-letter-spacing);
  padding: var(--cipher-space-surface-inset-sm);
  color: var(--cipher-muted);
}
.editor {
  display: grid;
  gap: var(--cipher-space-8);
  min-width: 0;
